// DTO matches api/src/referrals/projections/referral-portal.view.ts. Monetary
// values are kobo. These records only exist in the isolated browser test server.
export function workspace(user = 'user_a', scenario = '') {
  const owner = user === 'user_a' ? 'Adanna Okafor' : 'Bola Ade';
  const rows = [['paid', 'Royal Suites', 'PAYING', 'Paying customer', 2_000_000], ['retained', 'Palm House', 'RETAINED', 'Paying customer', 4_000_000], ['trial', 'Lagoon Lodge', 'TRIAL', 'On trial', 0], ['pending', 'Orchid Hotel', 'REFERRED', 'Referred', 0], ['closed', 'Closed Hotel', 'DISQUALIFIED', 'Closed', 0]];
  const referrals = rows.map(([id, name, lifecycle, statusLabel, totalEarnedMinor]) => ({ referralId: `${user}-${id}`, businessDisplayName: name, lifecycle, statusLabel, attributionStatus: id === 'pending' ? 'PENDING' : 'CONFIRMED', milestones: [{label:'Introduced to Innbase',reached:true},{label:'Became a paying customer',reached:totalEarnedMinor>0}], initialRewardStatus:totalEarnedMinor ? 'AVAILABLE':'NOT_EARNED', retentionRewardStatus:id==='retained'?'AVAILABLE':'NOT_EARNED', retentionRewardVisible:id==='retained', totalEarnedMinor, createdAt:'2026-09-01T10:00:00Z', updatedAt:'2026-09-20T10:00:00Z' }));
  const rewards = [['initial', 'paid', 'INITIAL_REFERRAL', 'AVAILABLE'], ['old', 'retained', 'INITIAL_REFERRAL', 'PAID'], ['bonus', 'retained', 'RETENTION_BONUS', 'AVAILABLE']].map(([id,r,type,status]) => ({rewardId:`${user}-${id}`, referralId:`${user}-${r}`,businessDisplayName:r==='paid'?'Royal Suites':'Palm House',type,typeLabel:type==='INITIAL_REFERRAL'?'Initial referral':'Retention bonus',amountMinor:2_000_000,currency:'NGN',status,earnedAt:'2026-09-20T10:00:00Z'}));
  const view = {referrerId:`referrer-${user}`,displayName:owner,email:`${user}@example.test`,phone:null,referrerStatus:'ACTIVE',referralToken:`token-${user}`,totalEarnedMinor:6_000_000,availableMinor:4_000_000,pendingMinor:0,withdrawnMinor:2_000_000,referralCount:5,currency:'NGN',canCreateReferrals:true,canRequestWithdrawal:true,referrals,rewards,withdrawals:[{withdrawalId:`old-${user}`,amountMinor:2_000_000,currency:'NGN',status:'PAID',maskedAccountNumber:'••••6789',bankName:'Example Bank',requestedAt:'2026-08-01T10:00:00Z',settledAt:'2026-08-02T10:00:00Z'}],consistencyClass:1,generatedAt:'2026-09-21T10:00:00Z',projectionVersion:'1.0.0'};
  if (scenario==='empty' || user==='user_b') Object.assign(view,{referrals:[],rewards:[],withdrawals:[],referralCount:0,totalEarnedMinor:0,availableMinor:0,pendingMinor:0,withdrawnMinor:0,canRequestWithdrawal:false});
  if (scenario==='suspended') Object.assign(view,{referrerStatus:'SUSPENDED',canCreateReferrals:false,canRequestWithdrawal:false});
  if (scenario==='long') { view.referrals[0].businessDisplayName='VeryLongHotelName'.repeat(18); view.email='VeryLongEmailAddress'.repeat(12)+'@example.test'; view.referralToken='longtoken'.repeat(30); }
  return view;
}
